From 4bc7674f3d63363c452d307b5fe6afdd46c0d235 Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Sat, 21 Nov 2026 13:07:19 +0100
Subject: [PATCH] plasmacomponents3: make Label follow system font changes

Labels in Plasma kept the font they were created with, because Plasma
windows don't propagate font changes to existing items and the Plasma
theme never refreshed its fonts. Refresh them and bind Label to them.

BUG: 480004
---
 .../kirigamiplasmastyle/plasmatheme.cpp       | 38 ++++++++++---------
 .../kirigamiplasmastyle/plasmatheme.h         |  1 +
 .../kirigamiplasmastyle/plugin.cpp            | 15 +++++++-
 .../kirigamiplasmastyle/plugin.h              |  6 +++
 .../plasmacomponents3/Label.qml               |  2 +-
 5 files changed, 43 insertions(+), 19 deletions(-)

diff --git a/src/declarativeimports/kirigamiplasmastyle/plasmatheme.cpp b/src/declarativeimports/kirigamiplasmastyle/plasmatheme.cpp
index eb317484e..1ed40979e 100644
--- a/src/declarativeimports/kirigamiplasmastyle/plasmatheme.cpp
+++ b/src/declarativeimports/kirigamiplasmastyle/plasmatheme.cpp
@@ -36,23 +36,7 @@ PlasmaTheme::PlasmaTheme(QObject *parent)
         });
     }

-    setDefaultFont(qGuiApp->font());
-
-    KSharedConfigPtr ptr = KSharedConfig::openConfig();
-    KConfigGroup general(ptr->group(QStringLiteral("general")));
-
-    setSmallFont(general.readEntry("smallestReadableFont", []() {
-        auto smallFont = qApp->font();
-#ifndef Q_OS_WIN
-        if (smallFont.pixelSize() != -1) {
-            smallFont.setPixelSize(smallFont.pixelSize() - 2);
-        } else {
-            smallFont.setPointSize(smallFont.pointSize() - 2);
-        }
-#endif
-        return smallFont;
-    }()));
-
+    syncFonts();
     syncWindow();
     syncColors();
     connect(&m_theme, &Plasma::Theme::themeChanged, this, &PlasmaTheme::syncColors);
@@ -164,6 +148,26 @@ void PlasmaTheme::syncColors()
     setFrameContrast(KColorScheme::frameContrast());
 }

+void PlasmaTheme::syncFonts()
+{
+    setDefaultFont(qGuiApp->font());
+
+    KSharedConfigPtr ptr = KSharedConfig::openConfig();
+    KConfigGroup general(ptr->group(QStringLiteral("general")));
+
+    setSmallFont(general.readEntry("smallestReadableFont", []() {
+        auto smallFont = qApp->font();
+#ifndef Q_OS_WIN
+        if (smallFont.pixelSize() != -1) {
+            smallFont.setPixelSize(smallFont.pixelSize() - 2);
+        } else {
+            smallFont.setPointSize(smallFont.pointSize() - 2);
+        }
+#endif
+        return smallFont;
+    }()));
+}
+
 void PlasmaTheme::syncFrameContrast()
 {
     if (QCoreApplication::closingDown()) {
diff --git a/src/declarativeimports/kirigamiplasmastyle/plasmatheme.h b/src/declarativeimports/kirigamiplasmastyle/plasmatheme.h
index 462c8713d..0cfa8c985 100644
--- a/src/declarativeimports/kirigamiplasmastyle/plasmatheme.h
+++ b/src/declarativeimports/kirigamiplasmastyle/plasmatheme.h
@@ -30,6 +30,7 @@ public:

     void syncWindow();
     void syncColors();
+    void syncFonts();
     void syncFrameContrast();

 protected:
diff --git a/src/declarativeimports/kirigamiplasmastyle/plugin.cpp b/src/declarativeimports/kirigamiplasmastyle/plugin.cpp
index 64540c6e4..0266c1bad 100644
--- a/src/declarativeimports/kirigamiplasmastyle/plugin.cpp
+++ b/src/declarativeimports/kirigamiplasmastyle/plugin.cpp
@@ -9,9 +9,12 @@
 #include "plasmatheme.h"
 #include "units.h"

+#include <QCoreApplication>
+
 Plugin::Plugin(QObject *parent)
     : Kirigami::Platform::PlatformPluginFactory(parent)
 {
+    QCoreApplication::instance()->installEventFilter(this);
 }

 Plugin::~Plugin() = default;
@@ -21,7 +24,9 @@ Kirigami::Platform::PlatformTheme *Plugin::createPlatformTheme(QObject *parent)
     Q_UNUSED(parent);
     // TODO: Implement a proper C++ version of PlatformTheme. This relies on fallback
     // behaviour in Kirigami to load the Theme.qml file.
-    return new PlasmaTheme(parent);
+    auto theme = new PlasmaTheme(parent);
+    connect(this, &Plugin::fontsChanged, theme, &PlasmaTheme::syncFonts);
+    return theme;
 }

 Kirigami::Platform::Units *Plugin::createUnits(QObject *parent)
@@ -30,4 +35,12 @@ Kirigami::Platform::Units *Plugin::createUnits(QObject *parent)
     return new Units(parent);
 }

+bool Plugin::eventFilter(QObject *watched, QEvent *event)
+{
+    if (watched == QCoreApplication::instance() && event->type() == QEvent::ApplicationFontChange) {
+        Q_EMIT fontsChanged();
+    }
+    return Kirigami::Platform::PlatformPluginFactory::eventFilter(watched, event);
+}
+
 #include "moc_plugin.cpp"
diff --git a/src/declarativeimports/kirigamiplasmastyle/plugin.h b/src/declarativeimports/kirigamiplasmastyle/plugin.h
index f51ea4de0..2a0c5a869 100644
--- a/src/declarativeimports/kirigamiplasmastyle/plugin.h
+++ b/src/declarativeimports/kirigamiplasmastyle/plugin.h
@@ -25,6 +25,12 @@ public:

     Kirigami::Platform::PlatformTheme *createPlatformTheme(QObject *parent) override;
     Kirigami::Platform::Units *createUnits(QObject *parent) override;
+
+Q_SIGNALS:
+    void fontsChanged();
+
+protected:
+    bool eventFilter(QObject *watched, QEvent *event) override;
 };

 #endif // PLUGIN_H
diff --git a/src/declarativeimports/plasmacomponents3/Label.qml b/src/declarativeimports/plasmacomponents3/Label.qml
index dd2647361..66f782120 100644
--- a/src/declarativeimports/plasmacomponents3/Label.qml
+++ b/src/declarativeimports/plasmacomponents3/Label.qml
@@ -23,7 +23,7 @@ T.Label {

     activeFocusOnTab: false

-    //font data is the system one by default
+    font: Kirigami.Theme.defaultFont
     color: Kirigami.Theme.textColor
     linkColor: Kirigami.Theme.linkColor

